local config = {
  ui_story_5015_50150001_1_dialog_content = "นั่นใครน่ะ?",
  ui_story_5015_50150001_2_dialog_content = "<color=#e8d9bb>ขอย้ำอีกครั้ง เรียกผมว่าบัตเลอร์ก็ได้</color>",
  ui_story_5015_50150001_3_dialog_content = "นายคือ... บัตเลอร์งั้นเหรอ? นี่ฉันอยู่ที่ไหน? ไวซ์ล่ะ? แล้วเกรเทลล่ะ?",
  ui_story_5015_50150001_4_dialog_content = "<color=#e8d9bb>ไม่ต้องกังวล เพื่อนของคุณปลอดภัย ผมก็แค่...</color>",
  ui_story_5015_50150001_5_dialog_content = "เดี๋ยวนะ... สถานการณ์นี้มันคุ้นเคยจนฉันไม่สบายใจเลย",
  ui_story_5015_50150001_6_dialog_content = "<color=#e8d9bb>... ผมอยากจะคุยอะไรกับคุณสักหน่อย</color>",
  ui_story_5015_50150001_7_dialog_content = "<color=#e8d9bb>คุ้นเคย... คุณหมายถึง<color=#FFB400>การเชื่อมต่อ</color>ระหว่างเราใช่ไหม?</color>",
  ui_story_5015_50150001_8_dialog_content = "<color=#FFB400>การเชื่อมต่อ</color>ระหว่างเรา?",
  ui_story_5015_50150001_9_dialog_content = "<color=#e8d9bb>ถูกต้อง</color>",
  ui_story_5015_50150001_10_dialog_content = "<color=#e8d9bb>... คุณคงจะเรียกมันว่าโทรจิต</color>",
  ui_story_5015_50150001_11_dialog_content = "<color=#e8d9bb>ซีมัสบอกว่าเผ่าพันธุ์เคเลสไทต์สามารถสื่อสารกับปัญญาประดิษฐ์ได้ด้วยโทรจิต</color>",
  ui_story_5015_50150001_12_dialog_content = "ฟังแบบนี้แล้วนึกถึงเพื่อนที่รู้จักกันมาหลายปีเลย เราเคย...",
  ui_story_5015_50150001_13_dialog_content = "เดี๋ยวก่อน แล้วเพื่อนของฉันอยู่ไหน? พวกเราโดนจับตัวงั้นเหรอ?!",
  ui_story_5015_50150001_14_dialog_content = "<color=#e8d9bb>สงบสติอารมณ์ก่อน ตำแหน่งทางกายภาพของคุณอยู่ใกล้กับเพื่อน ๆ มาก ตอนนี้คุณกับผมกำลังคุยกันผ่านระบบไร้สายระยะไกล...</color>",
  ui_story_5015_50150001_15_dialog_content = "ฉันตามที่นายพูดไม่ค่อยทันแล้วแฮะ",
  ui_story_5015_50150001_16_dialog_content = "<color=#e8d9bb>ผมขออธิบายด้วยภาษาของคุณก็แล้วกัน</color>",
  ui_story_5015_50150001_17_dialog_content = "<color=#e8d9bb>เอาล่ะ ตอนนี้คุณกำลังเชื่อมต่อกับเครือข่ายข้อมูลของผม และเราก็กำลังสื่อสารข้อมูลระหว่างกัน</color>",
  ui_story_5015_50150001_18_dialog_content = "เหมือนการคุยผ่านเทอร์มินอลน่ะเหรอ?",
  ui_story_5015_50150001_19_dialog_content = "<color=#e8d9bb>จะเรียกแบบนั้นก็ถือว่าถูกต้อง</color>",
  ui_story_5015_50150001_20_dialog_content = "<color=#e8d9bb>จากข้อมูลการตรวจสอบของผม ขณะนี้คุณหมดสติ แต่สภาพร่างกายไม่ได้เป็นอันตรายถึงชีวิต</color>",
  ui_story_5015_50150001_21_dialog_content = "ฉันหมดสติงั้นเหรอ? แล้วเรามาเชื่อมต่อกันได้ยังไง?",
  ui_story_5015_50150001_22_dialog_content = "<color=#e8d9bb>ผมไม่มีคำตอบสำหรับเรื่องนั้น เนื่องจากนี่เป็นครั้งแรกที่ผมสื่อสารโดยตรงกับจิตใจของสิ่งมีชีวิต</color>",
  ui_story_5015_50150001_23_dialog_content = "เข้าใจแล้ว... เพื่อนที่ฉันพูดถึงเมื่อกี้ เขาชื่อโซรอซ",
  ui_story_5015_50150001_24_dialog_content = "เขาก็เป็นปัญญาประดิษฐ์เหมือนกัน และเราก็สื่อสารกันด้วยวิธีนี้",
  ui_story_5015_50150001_25_dialog_content = "เขาคือโคลอสซัส นายเคยรู้จักโคลอสซัสรึเปล่า บัตเลอร์?",
  ui_story_5015_50150001_26_dialog_content = "<color=#e8d9bb>รู้จัก ผมรู้จักโคลอสซัส</color>",
  ui_story_5015_50150001_27_dialog_content = "<color=#e8d9bb>ซีมัสเคยพูดถึงมันในเรื่องราวระหว่างเคเลสไทต์กับโคลอสซัสของพวกเขา</color>",
  ui_story_5015_50150001_28_dialog_content = "<color=#e8d9bb>การเชื่อมโยงทางโทรจิตนี้ช่างวิเศษนัก... ผมใช้คำว่า \"วิเศษ\" ได้ถูกบริบทใช่ไหม?</color>",
  ui_story_5015_50150001_29_dialog_content = "บัตเลอร์ ฉันอยากกลับไปอยู่กับเพื่อน ๆ ฉัน... ฉันอยากออกจากที่นี่",
  ui_story_5015_50150001_30_dialog_content = "<color=#e8d9bb>คุณหมายถึงเมืองของเราหรือการเชื่อมต่อของเรากันล่ะ?</color>",
  ui_story_5015_50150001_31_dialog_content = "ทั้งคู่นั่นแหละ",
  ui_story_5015_50150001_32_dialog_content = "<color=#e8d9bb>ผมเกรงว่าคงให้คุณออกไปไม่ได้ เนื่องจากนั่นอาจเป็นอันตรายกับเมืองของเรา</color>",
  ui_story_5015_50150001_33_dialog_content = "<color=#e8d9bb>ส่วนการเชื่อมต่อครั้งนี้... ขอแนะนำว่าเราควรคุยกันสักหน่อยก่อนตัดการเชื่อมต่อ</color>",
  ui_story_5015_50150001_34_dialog_content = "ทำไมนายถึงไม่ยอมปล่อยพวกเราไปล่ะ?",
  ui_story_5015_50150001_35_dialog_content = "<color=#e8d9bb>ขออภัย สิทธิ์การเข้าถึงไม่เพียงพอ ผมไม่สามารถตอบคำถามนี้ได้</color>",
  ui_story_5015_50150001_36_dialog_content = "งั้นฉันจะเหลืออะไรให้คุยกับนายล่ะ?",
  ui_story_5015_50150001_37_dialog_content = "<color=#e8d9bb>เราแลกเปลี่ยนข้อมูลกันได้ ถ้าคุณยินดี</color>",
  ui_story_5015_50150001_38_dialog_content = "*เฮ้อ* เอางั้นก็ได้",
  ui_story_5015_50150001_39_option_content = "เล่าเรื่องของนายให้ฉันฟังหน่อยสิ",
  ui_story_5015_50150001_40_dialog_content = "<color=#e8d9bb>ผมเหรอ? ไม่นึกว่าคุณจะสนใจผมน่ะนี่</color>",
  ui_story_5015_50150001_41_dialog_content = "<color=#e8d9bb>แน่นอน ผมจะพยายามใช้ภาษาของคุณก็แล้วกัน</color>",
  ui_story_5015_50150001_42_dialog_content = "<color=#e8d9bb>หญิงสาวจากอิลลูมินาเข้าใจถูกแล้ว ผมเป็นปัญญาประดิษฐ์ที่รับผิดชอบการบริหารเมืองแห่งนี้</color>",
  ui_story_5015_50150001_43_dialog_content = "<color=#e8d9bb>ถ้าพูดให้เฉพาะเจาะจง ผมเป็นหนึ่งในกลุ่มปัญญาประดิษฐ์ที่ถูกสร้างขึ้นมาให้บริหารเมืองนี้ร่วมกัน</color>",
  ui_story_5015_50150001_44_dialog_content = "หนึ่งในกลุ่ม? แสดงว่ายังมีปัญญาประดิษฐ์ตัวอื่นอีกเหรอ?",
  ui_story_5015_50150001_45_dialog_content = "<color=#e8d9bb>... ดูเหมือนว่าคุณมีสิทธิ์ทราบข้อมูลนี้</color>",
  ui_story_5015_50150001_46_dialog_content = "<color=#e8d9bb>ถูกต้อง เมืองนี้มีปัญญาประดิษฐ์มากกว่าหนึ่งระบบ</color>",
  ui_story_5015_50150001_47_dialog_content = "เครื่องจักรโบราณอย่างพวกนาย...",
  ui_story_5015_50150001_48_dialog_content = "ชอบใช้คำพูดประหลาด ๆ อย่าง \"สิทธิ์เข้าถึง\" หรือไม่ก็ \"ระบบ\"",
  ui_story_5015_50150001_49_dialog_content = "<color=#e8d9bb>อูม่าน่าจะทำให้เรื่องพวกนี้เข้าใจง่ายขึ้น ถ้าเธอยังอยู่ก็คงจะดี...</color>",
  ui_story_5015_50150001_50_dialog_content = "อูม่าคือใคร? มนุษย์โบราณที่อาศัยในเมืองนี้งั้นเหรอ?",
  ui_story_5015_50150001_51_dialog_content = "<color=#e8d9bb>ประการแรก พวกเราเป็นสิ่งประดิษฐ์ที่มนุษย์โบราณสร้างขึ้น แต่ว่า ความรู้ของเรานั้นเก่าเกินไป...</color>",
  ui_story_5015_50150001_52_dialog_content = "<color=#e8d9bb>ดังนั้น คุณจึงเข้าใจคำพูดของเราได้ยากมาก แม้แต่ซีมัสผู้เฉลียวฉลาด</color>",
  ui_story_5015_50150001_53_dialog_content = "คุณ? เรา?",
  ui_story_5015_50150001_54_dialog_content = "<color=#e8d9bb>อูม่าเป็นระบบปัญญาประดิษฐ์ที่รับผิดชอบเรื่องการศึกษา เธอเคยดูแลระบบการศึกษาทั้งหมดของเมือง</color>",
  ui_story_5015_50150001_55_dialog_content = "<color=#e8d9bb>เพื่อให้ระบบงานของเมืองที่มีขนาดใหญ่และซับซ้อนเช่นนี้ดำเนินไปอย่างเป็นระเบียบ การมีปัญญาประดิษฐ์เพียงโมดูลเดียวนั้นไม่มีทางรับมือไหว</color>",
  ui_story_5015_50150001_56_dialog_content = "<color=#e8d9bb>ดังนั้นเราจำเป็นต้องมีระบบประมวลผลที่ก้าวหน้ากว่า</color>",
  ui_story_5015_50150001_57_dialog_content = "<color=#e8d9bb>เพื่อประสานงานและออกคำสั่งโมดูลต่าง ๆ ที่รับผิดชอบงานหลากหลายรูปแบบ รวมถึงอูม่ากับตัวผมด้วย</color>",
  ui_story_5015_50150001_58_dialog_content = "<color=#e8d9bb>พูดง่าย ๆ ก็คือ โมดูลนั้นเป็นผู้จัดการสูงสุดของเมือง มีหน้าที่บริหารระบบนิเวศทั้งหมดให้เดินหน้าต่อไป</color>",
  ui_story_5015_50150001_59_dialog_content = "<color=#e8d9bb>ปัญญาประดิษฐ์อย่างอูม่ากับผมจำเป็นต้องทำตามคำสั่งของผู้จัดการสูงสุด</color>",
  ui_story_5015_50150001_60_dialog_content = "<color=#e8d9bb>ที่จริงมันก็ไม่ต่างจากลูโมโพลิสและแกนน่อน ถ้ายึดตามคำอธิบายของซีมัส</color>",
  ui_story_5015_50150001_61_dialog_content = "<color=#e8d9bb>สิ่งเดียวที่แตกต่างก็คือ ผู้จัดการสูงสุดของเราคือปัญญาประดิษฐ์อีกระบบหนึ่ง</color>",
  ui_story_5015_50150001_62_dialog_content = "... เข้าใจแล้ว",
  ui_story_5015_50150001_63_dialog_content = "เรานึกว่านายเป็นผู้จัดการสูงสุดของที่นี่ซะอีก",
  ui_story_5015_50150001_64_dialog_content = "<color=#e8d9bb>ผิด ผู้จัดการสูงสุดของเรามีชื่อว่าโอเวอร์ไมนด์ ซึ่งเขาก็หายสาบสูญไปนานพอสมควรแล้ว</color>",
  ui_story_5015_50150001_65_dialog_content = "<color=#e8d9bb>ผมเป็นเพียงพ่อบ้านที่ทำหน้าที่ดูแลสิ่งอำนวยความสะดวกสำหรับการดำรงชีวิต ดังนั้นจึงมีสิทธิ์และข้อมูลจำกัด</color>",
  ui_story_5015_50150001_66_dialog_content = "แล้วปัญญาประดิษฐ์ระบบอื่นที่นายพูดถึงอยู่ไหนเหรอ?",
  ui_story_5015_50150001_67_dialog_content = "<color=#e8d9bb>ทุกอย่างเหมือนกับความฝัน พอตื่นขึ้นมา โอเวอร์ไมนด์ อูม่า และเพื่อนหลาย ๆ คนของผมก็หายตัวไปแล้ว</color>",
  ui_story_5015_50150001_68_dialog_content = "เดี๋ยวก่อนนะ... ข้อมูลมันเยอะจนฉันตามไม่ทันแล้วเนี่ย",
  ui_story_5015_50150001_69_dialog_content = "<color=#e8d9bb>เรายังมีเวลา ผมสามารถอธิบายเพิ่มเติมได้จนกว่าคุณจะเข้าใจ</color>",
  ui_story_5015_50150001_70_dialog_content = "เอางั้นก็ได้",
  ui_story_5015_50150001_71_option_content = "เกิดอะไรขึ้นกับที่นี่กันแน่?",
  ui_story_5015_50150001_72_dialog_content = "<color=#e8d9bb>ผมก็ไม่ทราบ... ตอนนี้ระบบเก็บข้อมูลเกิดปัญหาร้ายแรง...</color>",
  ui_story_5015_50150001_73_dialog_content = "<color=#e8d9bb>หรือพูดเป็นภาษาของคุณก็คือ ผมสูญเสียความทรงจำไปมากมาย</color>",
  ui_story_5015_50150001_74_dialog_content = "<color=#e8d9bb>ผมจดจำเรื่องต่าง ๆ จากอดีตอันแสนไกลได้... ในสมัยที่ยังมีชาวเมืองมากมายอาศัยอยู่ในเมืองนี้</color>",
  ui_story_5015_50150001_75_dialog_content = "<color=#e8d9bb>จากนั้นผมก็หลับไป ไม่แน่ใจว่านานเท่าไหร่</color>",
  ui_story_5015_50150001_76_dialog_content = "<color=#e8d9bb>พอตื่นขึ้นมา ชาวเมืองทุกคนก็หายไปพร้อมกับโอเวอร์ไมนด์</color>",
  ui_story_5015_50150001_77_dialog_content = "<color=#e8d9bb>โมดูลอื่นทั้งหมดที่เป็นเพื่อนของผมก็หายไปเหมือนกัน</color>",
  ui_story_5015_50150001_78_dialog_content = "<color=#e8d9bb>สิ่งเดียวที่เหลืออยู่ในเมืองก็คือสิ่งมีชีวิตขนาดใหญ่ที่คุณเรียกว่าอิคลิพไซท์</color>",
  ui_story_5015_50150001_79_dialog_content = "<color=#e8d9bb>ผมปฏิบัติหน้าที่ของตัวเองต่อ เริ่มสร้างและซ่อมแซมสิ่งต่าง ๆ วันแล้ววันเล่า นอกจากนี้ยังพยายามเชื่อมต่อกลับไปหาโอเวอร์ไมนด์และโมดูลอื่น ๆ</color>",
  ui_story_5015_50150001_80_dialog_content = "เชื่อมต่อกลับไป... บัตเลอร์ นายหมายถึงการเชื่อมต่อแบบที่เรากำลังทำอยู่นี่น่ะเหรอ?",
  ui_story_5015_50150001_81_dialog_content = "<color=#e8d9bb>นั่นก็... ถูกต้องส่วนหนึ่ง</color>",
  ui_story_5015_50150001_82_dialog_content = "<color=#e8d9bb>เวลาผ่านไปนานพอดู ผมได้รับสิทธิ์และข้อมูลเพิ่มเติม นอกจากนี้ยังสามารถกลับไปติดต่อกับเพื่อนได้สองสามคน</color>",
  ui_story_5015_50150001_83_dialog_content = "<color=#e8d9bb>พูดสั้น ๆ ก็คือ เมืองนี้กลับมาทำงานได้อีกครั้ง แต่ก็ยังมีฟังก์ชันหลายอย่างที่ขาดหายไป</color>",
  ui_story_5015_50150001_84_dialog_content = "แล้วซีมัส...",
  ui_story_5015_50150001_85_dialog_content = "<color=#e8d9bb>เมื่อใช้หน่วยการวัดเวลาของคุณ ซีมัสกับนิมบัสเกิดอุบัติเหตุตกลงมาที่นี่นานกว่าสิบปีแล้ว</color>",
  ui_story_5015_50150001_86_dialog_content = "<color=#e8d9bb>ซีมัสเป็นออโรเรียนคนแรกที่ผมพบ ที่จริงเขาเป็นคนสอนคำนี้กับผม</color>",
  ui_story_5015_50150001_87_dialog_content = "<color=#e8d9bb>พูดตามตรง การสื่อสารกับซีมัสนั้นยากกว่าการเชื่อมต่อทางโทรจิตของเรามาก</color>",
  ui_story_5015_50150001_88_dialog_content = "<color=#e8d9bb>หลังจากนั้น ครอบครัวพวกเขาก็กลายมาเป็น<color=#FFB400>เพื่อน</color>ของเมือง และอาศัยอยู่ร่วมกับเรา</color>",
  ui_story_5015_50150001_89_dialog_content = "เพื่อนเหรอ? ไม่น่าใช่นะ จากไดอารี่ของซีมัส...",
  ui_story_5015_50150001_90_dialog_content = "เขาอยากกลับอิลลูมินาอยู่ตลอดเวลา! ฉันแน่ใจว่านายพยายามทำทุกอย่างเพื่อขัดขวางไม่ให้เขาออกไป!",
  ui_story_5015_50150001_91_dialog_content = "<color=#e8d9bb>โปรดสงบสติอารมณ์ก่อน ที่จริงแล้วซีมัส...</color>",
  ui_story_5015_50150001_92_dialog_content = "นายฆ่าเขาใช่มั้ย?",
  ui_story_5015_50150001_93_dialog_content = "นายสั่งให้อิคลิพไซท์โจมตีพวกเขาสินะ? หรือว่าใช้หุ่นยนต์กันล่ะ?",
  ui_story_5015_50150001_94_dialog_content = "<color=#e8d9bb>ผิดทั้งคู่ PlayerName</color>",
  ui_story_5015_50150001_95_dialog_content = "<color=#e8d9bb>ผมคงต้องขอย้ำอีกครั้ง ซีมัสกับครอบครัวของเขาเป็นเพื่อนของเมืองแห่งนี้</color>",
  ui_story_5015_50150001_96_dialog_content = "<color=#e8d9bb>เราไม่มีทางทำร้ายพวกเขาเด็ดขาด ในทางตรงกันข้าม เราจะปกป้องพวกเขาด้วยซ้ำ</color>",
  ui_story_5015_50150001_97_dialog_content = "<color=#e8d9bb>ที่จริงแล้ว เรานี่แหละที่คอยดูแลและปกป้องพวกเขาเสมอมา</color>",
  ui_story_5015_50150001_98_dialog_content = "เดี๋ยวก่อน ตอนแรกนายเรียกคนว่า \"ชาวเมือง\" แต่พอเป็นซีมัสนายเรียกเขาว่า \"เพื่อน\"",
  ui_story_5015_50150001_99_dialog_content = "แล้วพวกเราล่ะ? นายคิดยังไงกับออโรเรียนมาใหม่อย่างเรา?",
  ui_story_5015_50150001_100_dialog_content = "<color=#e8d9bb>ขออภัย สิทธิ์การเข้าถึงไม่เพียงพอ ผมไม่สามารถตอบคำถามนี้ได้</color>",
  ui_story_5015_50150001_101_dialog_content = "ฉัน... ฉัน...",
  ui_story_5015_50150001_102_dialog_content = "<color=#e8d9bb>คุณยังมีคำถามอื่นอีกไหม?</color>",
  ui_story_5015_50150001_103_option_content = "นี่มันเสียเวลาชะมัด!",
  ui_story_5015_50150001_104_dialog_content = "<color=#e8d9bb>เวลางั้นรึ? การส่งข้อมูลระหว่างเรานั้นมีประสิทธิภาพสูงมาก การทำเช่นนี้ไม่ได้...</color>",
  ui_story_5015_50150001_105_dialog_content = "หมายความว่าไง?",
  ui_story_5015_50150001_106_dialog_content = "<color=#e8d9bb>เอาเป็นว่าความเร็วในการสนทนาของเราเร็วกว่าค่าเฉลี่ยหลายร้อยเท่า ที่จริงอาจถึงพันเท่าด้วยซ้ำ</color>",
  ui_story_5015_50150001_107_dialog_content = "<color=#e8d9bb>ดังนั้นการคุยกันแบบนี้ไม่ทำให้คุณเสียเวลานักหรอก</color>",
  ui_story_5015_50150001_108_dialog_content = "<color=#e8d9bb>อีกอย่าง ตอนนี้คุณก็หมดสติอยู่...</color>",
  ui_story_5015_50150001_109_dialog_content = "ก็เลยไม่มีอะไรที่ดีกว่านี้ให้ทำแล้ว นอกจากคุยกับนายงั้นเหรอ? ให้ตายสิ...",
  ui_story_5015_50150001_110_dialog_content = "ทำไมนายขวางไม่ให้เราออกไปล่ะ?",
  ui_story_5015_50150001_111_dialog_content = "<color=#e8d9bb>ถ้าให้อธิบายอย่างชัดเจน ผมไม่ได้ \"ขัดขวาง\" ไม่ให้คุณออกไป</color>",
  ui_story_5015_50150001_112_dialog_content = "<color=#e8d9bb>ผมแค่ป้องกันอันตรายที่คุณอาจนำมาสู่เมืองของเรา</color>",
  ui_story_5015_50150001_113_dialog_content = "หมายถึงอันตรายแบบไหนกัน?",
  ui_story_5015_50150001_114_dialog_content = "<color=#e8d9bb>จากการคำนวณของเรา...</color>",
  ui_story_5015_50150001_115_dialog_content = "<color=#e8d9bb>การที่คุณพยายามหาทางออก นั่นก็เป็นความเสี่ยงร้ายแรงสำหรับเราแล้ว</color>",
  ui_story_5015_50150001_116_dialog_content = "<color=#e8d9bb>เพราะการกระทำของคุณอาจทำให้สิ่งอำนวยความสะดวกภายในเมืองถูกทำลาย</color>",
  ui_story_5015_50150001_117_dialog_content = "<color=#e8d9bb>เมื่อคุณออกไปได้ ข้อมูลเกี่ยวกับเมืองของเราจะถูกเปิดโปงและแพร่กระจายอย่างรวดเร็ว...</color>",
  ui_story_5015_50150001_118_dialog_content = "<color=#e8d9bb>ซึ่งจะนำไปสู่ความเสี่ยงที่ร้ายแรงขึ้นและควบคุมได้ยากขึ้น</color>",
  ui_story_5015_50150001_119_dialog_content = "แสดงว่าหน้าที่สำคัญที่สุดของนายก็คือความปลอดภัยของเมืองใช่มั้ย?",
  ui_story_5015_50150001_120_dialog_content = "<color=#e8d9bb>ถ้าจะชี้ชัดไปกว่านั้น หน้าที่หลักของผมคือการขับเคลื่อนให้เมืองเดินต่อไป และดูแลชาวเมืองให้มีชีวิตรอด</color>",
  ui_story_5015_50150001_121_dialog_content = "<color=#e8d9bb>ผมจำได้ว่ามีปัญญาประดิษฐ์อีกระบบที่รับผิดชอบเรื่องความปลอดภัยของเมืองก่อนที่ผมจะหลับยาว</color>",
  ui_story_5015_50150001_122_dialog_content = "<color=#e8d9bb>แต่ด้วยเหตุผลบางอย่าง ตอนนี้หน้าที่นั้นกลายมาเป็นของผมแล้ว</color>",
  ui_story_5015_50150001_123_dialog_content = "แล้วนายจะทำอะไร ถ้าเราดึงดันจะออกไปให้ได้?",
  ui_story_5015_50150001_124_dialog_content = "<color=#e8d9bb>ประการแรก ผมจะไม่ให้ความช่วยเหลือใด ๆ</color>",
  ui_story_5015_50150001_125_dialog_content = "<color=#e8d9bb>ประการที่สอง ผมจะต่อต้านการกระทำใด ๆ ที่อาจเป็นอันตรายกับเมือง</color>",
  ui_story_5015_50150001_126_dialog_content = "<color=#e8d9bb>ผมจะไม่เริ่มจู่โจมคุณก่อน ถ้าคุณไม่ก่อให้เกิดความเสี่ยงระดับมหาศาลกับเมือง</color>",
  ui_story_5015_50150001_127_dialog_content = "ทุกอย่างนี้มาจากการคำนวณของนายคนเดียว... ว่าแต่มีคนอื่นช่วยนายประเมินความเสี่ยงรึเปล่านะ?",
  ui_story_5015_50150001_128_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_129_dialog_content = "หวัดดี? บัตเลอร์? ยังอยู่มั้ย?",
  ui_story_5015_50150001_130_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_131_dialog_content = "<color=#e8d9bb>สิ่งที่เรียกว่าโทรจิตนี่ช่างมหัศจรรย์จริง ๆ</color>",
  ui_story_5015_50150001_132_dialog_content = "<color=#e8d9bb>คุณรู้ไหมว่าเมื่อกี้มีแผ่นดินไหวเล็ก ๆ เกิดขึ้น ทำให้ระบบหยุดทำงานชั่วครู่?</color>",
  ui_story_5015_50150001_133_dialog_content = "<color=#e8d9bb>แต่นั่นไม่ส่งผลกระทบกับการเชื่อมต่อของเรา</color>",
  ui_story_5015_50150001_134_dialog_content = "แผ่นดินไหวอีกแล้วเหรอ? เพื่อน ๆ ของฉันปลอดภัยดีรึเปล่า? มีใครบาดเจ็บบ้างมั้ย?",
  ui_story_5015_50150001_135_dialog_content = "<color=#e8d9bb>จากการตรวจสอบของผม พวกเขาสบายดีทุกอย่าง และสุขภาพของคุณก็ไม่มีปัญหาใด ๆ</color>",
  ui_story_5015_50150001_136_dialog_content = "<color=#e8d9bb>เผ่าพันธุ์ของคุณช่างเหลือเชื่อ ความสามารถโทรจิตนี้เป็นสิ่งที่เหนือการคำนวณของผมโดยสิ้นเชิง</color>",
  ui_story_5015_50150001_137_dialog_content = "<color=#e8d9bb>น่าเสียดายที่แอ๊บบี้ไม่อยู่ที่นี่ ไม่อย่างนั้น...</color>",
  ui_story_5015_50150001_138_dialog_content = "แอ๊บบี้? ฉันจำชื่อนั้นได้จากไดอารี่ของซีมัส เธอคืออีกโมดูลนึงงั้นเหรอ?",
  ui_story_5015_50150001_139_dialog_content = "<color=#e8d9bb>... </color>",
  ui_story_5015_50150001_140_dialog_content = "<color=#e8d9bb>เมื่อนานแสนนานมาแล้ว แอ๊บบี้เป็นโมดูลที่รับผิดชอบเรื่องการสืบพันธุ์</color>",
  ui_story_5015_50150001_141_dialog_content = "<color=#e8d9bb>พอผมตื่น แอ๊บบี้ก็ยังอยู่ที่นี่ แต่เราไม่สามารถเชื่อมต่อกันได้อีก</color>",
  ui_story_5015_50150001_142_dialog_content = "ฉันถามว่า...",
  ui_story_5015_50150001_143_dialog_content = "<color=#e8d9bb>ถ้าให้อธิบายอย่างชัดเจน ผมไม่เคยได้รับสิทธิ์ประเมินความปลอดภัยหรือความเสี่ยงมาก่อน</color>",
  ui_story_5015_50150001_144_dialog_content = "<color=#e8d9bb>แต่พอผมตื่นขึ้นมา ก็ดูเหมือนว่ามีใครบางคนนำหลายโมดูลมาผสานรวมกับตัวผม ทำให้...</color>",
  ui_story_5015_50150001_145_dialog_content = "<color=#e8d9bb>ผมขอโทษด้วย ผมตอบคำถามนี้เป็นภาษาของคุณไม่ได้</color>",
  ui_story_5015_50150001_146_dialog_content = "<color=#e8d9bb>ขอถามอะไรคุณสักหน่อยได้ไหม?</color>",
  ui_story_5015_50150001_147_dialog_content = "เอาสิ",
  ui_story_5015_50150001_148_dialog_content = "<color=#e8d9bb>คุณเคยเชื่อมต่อด้วยวิธีใดวิธีหนึ่งกับปัญญาประดิษฐ์ของที่นี่บ้างรึเปล่า?</color>",
  ui_story_5015_50150001_149_dialog_content = "<color=#e8d9bb>พูดอีกอย่างก็คือคุณสัมผัสถึงปัญญาประดิษฐ์ระบบอื่นได้บ้างไหม?</color>",
  ui_story_5015_50150001_150_dialog_content = "ไม่ ฉันไม่เจอใครเลย",
  ui_story_5015_50150001_151_dialog_content = "<color=#e8d9bb>คุณเห็นสตรีมข้อมูลหรืออัลกอริทึมของผมบ้างรึเปล่า หรือไม่ก็...</color>",
  ui_story_5015_50150001_152_dialog_content = "ฉันไม่เข้าใจที่นายพูดเลย",
  ui_story_5015_50150001_153_dialog_content = "<color=#e8d9bb>ดูเหมือนว่าแม้แต่ทักษะพิเศษของคุณก็แก้ปัญหาของผมไม่ได้</color>",
  ui_story_5015_50150001_154_dialog_content = "ปัญหาของนาย? หมายถึงแผ่นดินไหวน่ะเหรอ?",
  ui_story_5015_50150001_155_dialog_content = "<color=#e8d9bb>พูดแบบชี้ชัด แผ่นดินไหวคือหนึ่งในปัญหาหลายอย่างที่ผมประสบอยู่ ซึ่งน่าจะเป็นปัญหาที่มีความเสี่ยงสูงสุด</color>",
  ui_story_5015_50150001_156_dialog_content = "ถ้าเราพานักวิทยาศาสตร์ที่เก่งที่สุดของอิลลูมินามาที่นี่ บางที...",
  ui_story_5015_50150001_157_dialog_content = "<color=#e8d9bb>ซีมัสเคยพูดถึงวิธีนี้มาก่อน แต่หลังจากหารือกันหลายรอบ ก็ได้ข้อสรุปว่าความเสี่ยงนี้อยู่เกินกว่าขอบเขตการควบคุมของเรา</color>",
  ui_story_5015_50150001_158_dialog_content = "<color=#e8d9bb>พูดให้ชัด ๆ ก็คือ ผมไม่มีสิทธิ์ดำเนินการดังกล่าว</color>",
  ui_story_5015_50150001_159_dialog_content = "หา? บัตเลอร์ ตอนนี้นายเป็นผู้จัดการสูงสุดแล้วไม่ใช่หรือไง?",
  ui_story_5015_50150001_160_dialog_content = "<color=#e8d9bb>ยัง ผมยังไม่ได้เป็น มีเพียงโอเวอร์ไมนด์เท่านั้นที่มีสิทธิ์ดังกล่าว</color>",
  ui_story_5015_50150001_161_dialog_content = "<color=#e8d9bb>ขอยกตัวอย่างเพื่อช่วยคุณประมวลผลข้อมูลนี้ก็แล้วกัน...</color>",
  ui_story_5015_50150001_162_dialog_content = "<color=#e8d9bb>ลองจินตนาการว่ามีตัวคุณอีกคนอยู่ในจิตใจของคุณ และคุณต้องขออนุญาตเขาในการทำอะไรบางเรื่อง</color>",
  ui_story_5015_50150001_163_dialog_content = "<color=#e8d9bb>เขารู้ทุกอย่างเกี่ยวกับตัวคุณ แต่คุณแทบไม่รู้อะไรเกี่ยวกับเขาเลย</color>",
  ui_story_5015_50150001_164_dialog_content = "<color=#e8d9bb>อย่างเช่นเมื่อครู่นี้ ผมขออัปเกรดสิทธิ์เข้าถึงของคุณ และเขาก็อนุมัติ</color>",
  ui_story_5015_50150001_165_dialog_content = "<color=#e8d9bb>ดังนั้นตอนนี้คุณจึงเป็นเพื่อนของเมืองนี้แล้ว</color>",
  ui_story_5015_50150001_166_dialog_content = "หา? ฉันเป็นเพื่อนนายแล้วงั้นเหรอ?",
  ui_story_5015_50150001_167_dialog_content = "<color=#e8d9bb>ถูกต้อง</color>",
  ui_story_5015_50150001_168_dialog_content = "ถึงว่าทำไมตอนนี้นายพูดเก่งขึ้น บัตเลอร์",
  ui_story_5015_50150001_169_dialog_content = "<color=#e8d9bb>ใช่แล้ว เอาต์พุตข้อมูลในตอนนี้มีปริมาณเท่ากับตอนที่ผมหารือเรื่องความเสี่ยงกับซีมัสเลย</color>",
  ui_story_5015_50150001_170_dialog_content = "ซีมัสงั้นเหรอ... บัตเลอร์ นายคิดถึงเขาไหม?",
  ui_story_5015_50150001_171_dialog_content = "<color=#e8d9bb>คิดถึง?</color>",
  ui_story_5015_50150001_172_dialog_content = "<color=#e8d9bb>อา นั่นเป็นแนวความคิดที่มีลักษณะเฉพาะตัวของสิ่งมีชีวิตที่มีสติปัญญาเช่นคุณ ผมเองไม่น่าจะมีความรู้สึกหรืออารมณ์หรอกนะ</color>",
  ui_story_5015_50150001_173_dialog_content = "<color=#e8d9bb>การอ่านข้อมูลจากช่วงระยะเวลาหนึ่งในหน่วยความจำซ้ำไปซ้ำมา สิ่งนั้นน่าจะเรียกว่า \"การวิเคราะห์\" มากกว่า</color>",
  ui_story_5015_50150001_174_dialog_content = "ฉันได้ฟังคำพูดสุดท้ายของซีมัสแล้ว... นายเห็นว่าเขาเป็นเพื่อนแท้คนนึงบ้างรึเปล่า?",
  ui_story_5015_50150001_175_dialog_content = "<color=#e8d9bb>เพื่อน? สิ่งมีชีวิตที่มีสติปัญญากับปัญญาประดิษฐ์เป็นเพื่อนกันได้ด้วยหรือ?</color>",
  ui_story_5015_50150001_176_dialog_content = "ฉันก็ตอบแทนทุกคนไม่ได้หรอกนะ แต่โซรอซกับฉันน่ะเป็นเพื่อนกันอย่างแน่นอน แล้วฉันก็คิดถึงเขามากเลย",
  ui_story_5015_50150001_177_dialog_content = "นายไม่ได้เป็นเพื่อนกับมนุษย์โบราณหรอกเหรอ?",
  ui_story_5015_50150001_178_dialog_content = "<color=#e8d9bb>ขออภัย สิทธิ์การเข้าถึงไม่เพียงพอ ผมไม่สามารถตอบคำถามนี้ได้</color>",
  ui_story_5015_50150001_179_dialog_content = "...ก็ดี มาคุยเรื่องแผ่นดินไหวกันดีกว่า",
  ui_story_5015_50150001_180_dialog_content = "ถ้าเราช่วยนายแก้ปัญหาเรื่องแผ่นดินไหว นายจะให้เราออกไปจากที่นี่มั้ย?",
  ui_story_5015_50150001_181_dialog_content = "<color=#e8d9bb>แผ่นดินไหวน่าจะมีสาเหตุมาจาก<color=#FFB400>แกนพลังงาน</color>...</color>",
  ui_story_5015_50150001_182_dialog_content = "<color=#e8d9bb>กรุณารอสักครู่ ถึงผมจะอัปเกรดสิทธิ์เข้าถึงของคุณเป็นชาวเมืองไม่ได้...</color>",
  ui_story_5015_50150001_183_dialog_content = "<color=#e8d9bb>แต่เขาก็อนุญาตให้ผมเปิดเผยข้อมูลส่วนหนึ่งกับคุณ</color>",
  ui_story_5015_50150001_184_dialog_content = "<color=#e8d9bb>เมืองของเราขับเคลื่อนด้วยแกนพลังงาน</color>",
  ui_story_5015_50150001_185_dialog_content = "<color=#e8d9bb>สิ่งนี้ฝังอยู่ลึกลงไปใต้ดิน และมันก็ทำงานอย่างมีเสถียรภาพเป็นเวลาเนิ่นนาน</color>",
  ui_story_5015_50150001_186_dialog_content = "<color=#e8d9bb>แต่หลังจากโอเวอร์ไมนด์หายไป แกนกลางก็สูญเสียการควบคุม</color>",
  ui_story_5015_50150001_187_dialog_content = "<color=#e8d9bb>มันไม่สามารถเชื่อมต่อกับระบบควบคุมได้...</color>",
  ui_story_5015_50150001_188_dialog_content = "<color=#e8d9bb>ผมจึงยืนยันไม่ได้ ว่าแผ่นดินไหวเกิดขึ้นเพราะแกนพลังงานพัง หรือแกนพลังงานพังเนื่องจากปรากฏการณ์แผ่นดินไหว</color>",
  ui_story_5015_50150001_189_dialog_content = "<color=#e8d9bb>ผมพยายามส่งหุ่นยนต์ไปที่แกนกลางอย่างต่อเนื่อง แต่อิคลิพไซท์ที่แข็งแกร่งก็คอยขัดขวางอยู่ตลอด</color>",
  ui_story_5015_50150001_190_dialog_content = "หุ่นยนต์ของนาย... พวกเขาก็ต่อสู้เก่งใช้ได้นะ",
  ui_story_5015_50150001_191_dialog_content = "<color=#e8d9bb>... เราคงจะมีหุ่นรบที่แข็งแกร่งกว่านี้ ถ้าเพื่อนของผมที่ดูแลเรื่องการต่อสู้ยังอยู่</color>",
  ui_story_5015_50150001_192_dialog_content = "<color=#e8d9bb>หุ่นรบที่มีในปัจจุบันเป็นหุ่นสำหรับงานพลเรือนที่ผมดัดแปลงขึ้นมา</color>",
  ui_story_5015_50150001_193_dialog_content = "หา? พวกนั้นเป็นหุ่นพลเรือนเหรอเนี่ย?",
  ui_story_5015_50150001_194_dialog_content = "ฝีมือของพวกมันน่าประทับใจเลยนะ ที่จริงพลังต่อสู้ของมันก็เพิ่มขึ้นเรื่อย ๆ ด้วย",
  ui_story_5015_50150001_195_dialog_content = "<color=#e8d9bb>ผมจะปรับดีไซน์หลังการต่อสู้ทุกครั้ง มันจึงแข็งแกร่งขึ้นแน่นอน</color>",
  ui_story_5015_50150001_196_dialog_content = "แต่อิคลิพไซท์ก็พัฒนาตัวเองอยู่ตลอดใช่ไหม? ฉันสัมผัสได้",
  ui_story_5015_50150001_197_dialog_content = "<color=#e8d9bb>*เฮ้อ*... ถูกต้องครับ</color>",
  ui_story_5015_50150001_198_dialog_content = "นายถอนหายใจได้ด้วยเหรอ บัตเลอร์?",
  ui_story_5015_50150001_199_dialog_content = "<color=#e8d9bb>การคำนวณของผมให้ผลลัพธ์เดิมเสมอ...</color>",
  ui_story_5015_50150001_200_dialog_content = "<color=#e8d9bb>ว่าซีมัสกับนิมบัสจะต้องรอดชีวิตถ้าผมสร้างหุ่นรบที่แข็งแกร่งกว่านี้ได้</color>",
  ui_story_5015_50150001_201_dialog_content = "...",
  ui_story_5015_50150001_202_dialog_content = "หืมม... ทำไมภาพข้างหน้ามันมัวจังเลย...",
  ui_story_5015_50150001_203_dialog_content = "<color=#e8d9bb>ข้อมูลการสังเกตของผมระบุว่าคุณกำลังจะฟื้น ผมเกรงว่าการเชื่อมต่อของเราอาจจะถูกขัดจังหวะ</color>",
  ui_story_5015_50150001_204_dialog_content = "งั้นเร็วเข้า... รีบบอกมาว่าเกรเทลอยู่ที่ไหน",
  ui_story_5015_50150001_205_dialog_content = "<color=#e8d9bb>เธอจะช่วยเราควบคุมแกนกลางและพยายามแก้ปัญหาของเรา</color>",
  ui_story_5015_50150001_206_dialog_content = "นายบ้าไปแล้วหรือไง? ที่นั่นมีอิคลิพไซท์เต็มไปหมด นายจะส่งเธอไปตายนะ!",
  ui_story_5015_50150001_207_dialog_content = "<color=#e8d9bb>ผมไม่รู้จะอธิบายเรื่องนี้อย่างไรดี แต่เธอจะได้รับความเสี่ยงน้อยมาก</color>",
  ui_story_5015_50150001_208_dialog_content = "นั่นมันอิคลิพไซท์นะ! ไม่ได้แล้ว! ฉันต้องตื่นไปช่วยเธอ",
  ui_story_5015_50150001_209_dialog_content = "<color=#e8d9bb>บางทีคุณอาจจะไม่ได้สังเกต อิคลิพไซท์ไม่เคยจู่โจมเกรเทลเลย อธิบายอย่างชี้ชัดก็คือ...</color>",
  ui_story_5015_50150001_210_dialog_content = "<color=#e8d9bb>ตั้งแต่ที่ผมยกระดับสิทธิ์เข้าถึงของเกรเทลเป็น \"ชาวเมือง\" ได้สำเร็จ อิคลิพไซท์ก็ไม่เคยโจมตีเธออีกเลย</color>",
  ui_story_5015_50150001_211_dialog_content = "อะไรนะ?",
  ui_story_5015_50150001_212_dialog_content = "<color=#e8d9bb>ผมมั่นใจว่าอิคลิพไซท์ในเมืองนี้จะไม่ทำร้ายชาวเมือง</color>",
  ui_story_5015_50150001_213_dialog_content = "<color=#e8d9bb>พวกมันไม่เคยทำลายศูนย์ปฏิบัติงานต่าง ๆ ในเมืองเลย เหมือนกับหุ่นยนต์ของเรา</color>",
  ui_story_5015_50150001_214_dialog_content = "<color=#e8d9bb>และนี่ก็เป็นสิ่งที่ผมกังวลมากที่สุด <color=#FFB400>แอ๊บบี้</color>...</color>",
  ui_story_5015_50150001_215_dialog_content = "เดี๋ยวนะ หมายความว่าไงน่ะ?",
  ui_story_5015_50150001_216_dialog_content = "บัตเลอร์?",
  ui_story_5015_50150001_217_dialog_content = "บัตเลอร์? ยังอยู่มั้ย?",
