  ui_story_5015_50150501_146_dialog_content = "<color=#e8d9bb>คุณหลงเข้าไปในเครือข่ายข้อมูลที่ผมกับแอ๊บบี้อยู่ ซึ่งเป็นสิ่งที่อันตรายมาก...</color>",
