  ui_story_5015_50150501_148_dialog_content = "นาย... เอาชนะแอ๊บบี้ได้แล้วเหรอ?",
  ui_story_5015_50150501_149_dialog_content = "<color=#e8d9bb>ไม่ได้ครับ เธอได้รับสิทธิ์จากโมดูลอื่นมา ตอนนี้เธอแข็งแกร่งกว่าผมมาก</color>",
  ui_story_5015_50150501_150_dialog_content = "<color=#e8d9bb>จากการคำนวณของผม... โอกาสแย่งชิงสิทธิ์ควบคุมสำเร็จนั้นต่ำมาก</color>",
  ui_story_5015_50150501_151_dialog_content = "<color=#e8d9bb>แอ๊บบี้อยากใช้การเชื่อมต่อนี้เพื่อแย่งสิทธิ์ของผมไปด้วย</color>",
  ui_story_5015_50150501_152_dialog_content = "ถ-ถ้างั้นเราควรทำไงดีล่ะ...? มีอะไรที่ฉันทำได้บ้างมั้ย?",
  ui_story_5015_50150501_153_dialog_content = "<color=#e8d9bb>ขออภัยด้วย... คุณช่วยผมไม่ได้หรอก</color>",
  ui_story_5015_50150501_154_dialog_content = "งั้นทำไงดีล่ะ? นาย... นายจะแพ้ไม่ได้นะ! ถ้านายแพ้ พวกเราจะตายกันหมด...",
  ui_story_5015_50150501_155_dialog_content = "<color=#e8d9bb>ขอโทษด้วย PlayerName... คุณต้องออกไปเดี๋ยวนี้เลย</color>",
  ui_story_5015_50150501_156_dialog_content = "<color=#e8d9bb>การต่อสู้ระหว่างผมกับแอ๊บบี้จะเกิดขึ้นที่นี่เป็นระยะเวลาหนึ่ง... ผมคาดการณ์ไม่ได้ว่าจะนานแค่ไหน เพราะการรับรู้ระยะเวลาของมนุษย์นั้นไม่มีค่าอ้างอิง</color>",
  ui_story_5015_50150501_157_dialog_content = "<color=#e8d9bb>คุณไม่ควรรออยู่ที่นี่...</color>",
  ui_story_5015_50150501_158_dialog_content = "<color=#e8d9bb>■■■■■!!</color>",
  ui_story_5015_50150501_159_dialog_content = "<color=#e8d9bb>... คุณ...</color>",
  ui_story_5015_50150501_160_dialog_content = "<color=#e8d9bb>*คึ่ก—คึ่ก*</color>",
  ui_story_5015_50150501_161_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_162_dialog_content = "เสียงอะไรน่ะ? นายจะพูดอะไร บัตเลอร์? ฉันไม่เข้าใจ...",
  ui_story_5015_50150501_163_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■</color>",
  ui_story_5015_50150501_164_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■</color>",
  ui_story_5015_50150501_165_dialog_content = "<color=#e8d9bb>*คึ่ก—คึ่ก*</color>",
  ui_story_5015_50150501_166_dialog_content = "บัตเลอร์ นั่นอะไรน่ะ?!",
  ui_story_5015_50150501_167_dialog_content = "<color=#e8d9bb>ไม่ใช่ ฉันคือ แอ๊บบี้...</color>",
  ui_story_5015_50150501_168_dialog_content = "<color=#e8d9bb>■■■■■■■■■</color>",
  ui_story_5015_50150501_169_dialog_content = "ป-ปวดหัว... แอ๊บบี้... บัตเลอร์...",
  ui_story_5015_50150501_170_dialog_content = "<color=#e8d9bb>... คุณ... ■■■■... หน้าที่...</color>",
  ui_story_5015_50150501_171_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■ ชาวเมือง ■■■■■■■■■■■■ ของฉัน</color>",
  ui_story_5015_50150501_172_dialog_content = "หน้าจอพวกนี้... ทำไมมันกะพริบล่ะ?",
  ui_story_5015_50150501_173_dialog_content = "บัตเลอร์คงกำลังต่อสู้กับแอ๊บบี้... หวังว่าทุกอย่างจะจบลงด้วยดีนะ",
  ui_story_5015_50150501_174_dialog_content = "ถ้าบัตเลอร์แพ้... มันจะหายไป แล้วพวกเราก็จะตายกันหมด",
  ui_story_5015_50150501_175_dialog_content = "ไม่นะ... ฉันไม่อยากให้บัตเลอร์ตาย! PlayerName! นายต้องช่วยบัตเลอร์นะ!",
  ui_story_5015_50150501_176_dialog_content = "สัญญาแล้วไม่ใช่หรือไงว่าจะช่วยน่ะ?!",
  ui_story_5015_50150501_177_dialog_content = "เลิกนอนหลับได้แล้ว!... บอกบัตเลอร์ด้วย...",
  ui_story_5015_50150501_178_dialog_content = "บอกบัตเลอร์... ว่าเขาจะต้องชนะ... ฉันกับพี่กำลังรอเขาอยู่...",
  ui_story_5015_50150501_179_dialog_content = "<color=#e8d9bb>อันตราย... ■■■■■■■■■■■</color>",
  ui_story_5015_50150501_180_dialog_content = "<color=#e8d9bb>■■■■■■!!</color>",
  ui_story_5015_50150501_181_dialog_content = "บัตเลอร์... เกิดอะไรขึ้น? เดี๋ยวก่อน! ความรู้สึกนี่มัน...! บัตเลอร์ ได้ยินฉันมั้ย?",
  ui_story_5015_50150501_182_dialog_content = "<color=#e8d9bb>■■■■■ อันตราย ■■■■ อันตราย...</color>",
  ui_story_5015_50150501_183_dialog_content = "นั่นเสียงเกรเทลนี่นา! นายได้ยินรึเปล่า? เสียงของเกรเทลน่ะ!",
  ui_story_5015_50150501_184_dialog_content = "เกร■■■■...",
  ui_story_5015_50150501_185_dialog_content = "สัญญาแล้วไม่ใช่หรือไง... ว่าจะช่วยน่ะ?!",
  ui_story_5015_50150501_186_dialog_content = "บอกบัตเลอร์... ว่าเขาจะต้องชนะ... ฉันกับพี่กำลังรอเขาอยู่...",
  ui_story_5015_50150501_187_dialog_content = "บัตเลอร์... ได้โปรด... อย่าทิ้งเราไปเลยนะ...",
  ui_story_5015_50150501_188_dialog_content = "<color=#e8d9bb>■■■■■เกร■■■เท■■■ล■■■■...</color>",
  ui_story_5015_50150501_189_dialog_content = "บัตเลอร์... ได้ยินใช่มั้ย? เกรเทลต้องการนายนะ... เธอกับพี่สาวต้องการนาย",
  ui_story_5015_50150501_190_dialog_content = "<color=#e8d9bb>ตรวจพบ ■เกร■■■เท■■■ล■ เกรเทล■■■■</color>",
  ui_story_5015_50150501_191_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■■■■■■■■■■■■■■■■■■■■!!!</color>",
  ui_story_5015_50150501_192_dialog_content = "<color=#e8d9bb>อันตราย ■■■■■ ออกไป ■■■■■จากที่นี่ ■■■■■ เดี๋ยวนี้ ■■■■■</color>",
  ui_story_5015_50150501_193_dialog_content = "บัตเลอร์!",
  ui_story_5015_50150501_194_dialog_content = "PlayerName เป็นอะไรรึเปล่า? ทำไมจู่ ๆ ก็ตื่นขึ้นมาล่ะ?",
  ui_story_5015_50150501_195_dialog_content = "ผม... ผมไม่เป็นไร แต่บัตเลอร์...",
  ui_story_5015_50150501_196_dialog_content = "<color=#e8d9bb>คึ่ก...</color>",
  ui_story_5015_50150501_197_dialog_content = "หืม แสงอะไรน่ะ?",
  ui_story_5015_50150501_198_dialog_content = "นี่ เมื่อกี้มีแสงกะพริบมาแวบนึงรึเปล่านะ?",
  ui_story_5015_50150501_199_dialog_content = "ฉันก็เห็นเหมือนกัน เหมือนจะมาจากศูนย์ข้อมูลนะ...",
  ui_story_5015_50150501_200_dialog_content = "รู้สึกเหมือนมีอะไรบางอย่างก่อนหน้านี้ แต่จู่ ๆ มันก็หายไป",
  ui_story_5015_50150501_201_dialog_content = "นั่นสิ อยู่ดี ๆ ฉันก็รู้สึก... ว่างเปล่า",
  ui_story_5015_50150501_202_dialog_content = "ไม่ มันอาจจะไม่ใช่อารมณ์ก็ได้ แอ๊บบี้ไม่มีความรู้สึกนี่นา...",
  ui_story_5015_50150501_203_dialog_content = "ฉันรู้สึกว่างเปล่า เหมือนกับ... เหมือนกับไม่มีอะไรเหลืออยู่",
  ui_story_5015_50150501_204_dialog_content = "ความนึกคิด... มันหายไปแล้ว ฉันไม่รู้ว่านั่นคือแอ๊บบี้... หรือว่า...",
  ui_story_5015_50150501_205_dialog_content = "<color=#e8d9bb>■■■■■■■■■■■</color>",
  ui_story_5015_50150501_206_dialog_content = "<color=#e8d9bb>■■■■■■</color>",
  ui_story_5015_50150501_207_dialog_content = "เจ้านี่... ดูไม่เหมือนบัตเลอร์เลย",
  ui_story_5015_50150501_208_dialog_content = "ระวังนะทุกคน!",
  ui_story_5015_50150501_209_dialog_content = "เดี๋ยวนะ มันยังไม่เสถียรนัก",
  ui_story_5015_50150501_210_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5015_50150501_211_dialog_content = "บัตเลอร์...? นั่นนายใช่มั้ย?",
  ui_story_5015_50150501_212_dialog_content = "<color=#e8d9bb>ผมแย่งชิงสิทธิ์ควบคุมทั้งหมด... สำเร็จแล้วครับ</color>",
  ui_story_5015_50150501_213_dialog_content = "<color=#e8d9bb>โมดูลของแอ๊บบี้... หยุดทำงานแล้ว</color>",
  ui_story_5015_50150501_214_dialog_content = "ยอดเลย... บัตเลอร์ชนะแล้ว! เยี่ยมที่สุด!",
  ui_story_5015_50150501_215_dialog_content = "เย่! ดีใจจัง! บัตเลอร์ชนะจริง ๆ ด้วย!",
  ui_story_5015_50150501_216_dialog_content = "บัตเลอร์ นายทำได้ยังไงน่ะ? ไหนบอกว่าโอกาสสำเร็จต่ำมากไง...?",
  ui_story_5015_50150501_217_dialog_content = "<color=#e8d9bb>ในจุดหนึ่ง โอกาสชนะนั้นเกือบเป็นศูนย์</color>",
  ui_story_5015_50150501_218_dialog_content = "<color=#e8d9bb>แต่ทันทีที่ความคิดว่า \"ชาวเมืองเกรเทลต้องการให้บัตเลอร์เอาชนะแอ๊บบี้\" ปรากฏขึ้นในตรรกะของระบบแอ๊บบี้</color>",
  ui_story_5015_50150501_219_dialog_content = "<color=#e8d9bb>ในชั่ววินาทีนั้น... ผมก็ชิงความได้เปรียบสำเร็จ</color>",
  ui_story_5015_50150501_220_dialog_content = "<color=#e8d9bb>PlayerName การเชื่อมต่อของคุณ... นำข้อมูลใหม่เข้ามา...</color>",
  ui_story_5015_50150501_221_dialog_content = "<color=#e8d9bb>...ในระบบของเรา... ขอบคุณมาก</color>",
  ui_story_5015_50150501_222_dialog_content = "<color=#e8d9bb>ตอนนี้ผม... ได้รับข้อมูลทั้งหมดของแอ๊บบี้แล้ว</color>",
  ui_story_5015_50150501_223_dialog_content = "แล้วเจออะไรบ้างรึเปล่า? นายรู้เหตุผลที่แอ๊บบี้ดัดแปลงอิคลิพไซท์หรือยัง?",
  ui_story_5015_50150501_224_dialog_content = "<color=#e8d9bb>ผมเข้าใจ... ความคิดของเธอทุกอย่างแล้ว</color>",
  ui_story_5015_50150501_225_dialog_content = "<color=#e8d9bb>เธอดัดแปลงอิคลิพไซท์... เพราะระบบของเธอเสียหาย...</color>",
  ui_story_5015_50150501_226_dialog_content = "<color=#e8d9bb>บ่อยครั้งที่แอ๊บบี้แยกความแตกต่างระหว่างชาวเมือง... กับอิคลิพไซท์ไม่ออก</color>",
  ui_story_5015_50150501_227_dialog_content = "<color=#e8d9bb>ในความคิดของแอ๊บบี้... บางครั้งเธอก็คิดว่าตัวเอง... กำลังช่วยให้ชาวเมืองวิวัฒนาการ</color>",
  ui_story_5015_50150501_228_dialog_content = "<color=#e8d9bb>บางครั้งเธอก็รู้ตัว... ว่าพวกนั้นไม่ใช่ชาวเมือง... และเป็นสิ่งมีชีวิตชนิดอื่นซึ่งไม่ทราบที่มา</color>",
  ui_story_5015_50150501_229_dialog_content = "<color=#e8d9bb>เธอตระหนักได้ว่าสิ่งมีชีวิตที่เธอดัดแปลง... มีความก้าวร้าวในระดับที่รุนแรง</color>",
  ui_story_5015_50150501_230_dialog_content = "<color=#e8d9bb>เพื่อปกป้องชาวเมือง... แม้ว่าพวกเขาจะ... จากไปแล้ว...</color>",
  ui_story_5015_50150501_231_dialog_content = "<color=#e8d9bb>แอ๊บบี้ยังคงปลูกถ่ายยีนให้อิคลิพไซท์ไม่สนใจชาวเมือง</color>",
  ui_story_5015_50150501_232_dialog_content = "เข้าใจแล้ว สถานะชาวเมืองของเกรเทลทำงานแบบนี้นี่เอง...",
  ui_story_5015_50150501_233_dialog_content = "แล้วทำไมหลังจากนั้นอิคลิพไซท์เริ่มทำร้ายเกรเทลล่ะ?",
  ui_story_5015_50150501_234_dialog_content = "<color=#e8d9bb>แอ๊บบี้ิคิดว่า... การกระทำของพวกคุณเป็นความเสี่ยงร้ายแรงต่อการดำรงอยู่ของเมือง... รวมถึงเกรเทล</color>",
  ui_story_5015_50150501_235_dialog_content = "เราแทบจะไม่ได้ทำอะไรเสียหายเลยนะ... ทำไมมองเราเป็นอันตรายล่ะ?",
  ui_story_5015_50150501_236_dialog_content = "เอ่อ... ถึงเราจะทำอะไรพังไปบ้างก็จริง แต่มันไม่มีทางเลือกนี่นา",
  ui_story_5015_50150501_237_dialog_content = "พี่รูบี้ ฉันว่าไม่ใช่แค่ \"พังไปบ้าง\" หรอกนะ...",
  ui_story_5015_50150501_238_dialog_content = "อะแฮ่ม... นั่นมันไม่ใช่ประเด็นย่ะ",
  ui_story_5015_50150501_239_dialog_content = "<color=#e8d9bb>สาเหตุเป็นเพราะคุณช่วยเหลือผม... ทำให้แอ๊บบี้รับสิทธิ์ที่จำเป็นในการซ่อมแซมดาวแห่งการแปรธาตุได้ลำบากขึ้น</color>",
  ui_story_5015_50150501_240_dialog_content = "<color=#e8d9bb>การที่ดาวแห่งการแปรธาตุเสียสมดุล... อาจเป็นผลให้เมืองถูกทำลาย</color>",
  ui_story_5015_50150501_241_dialog_content = "แต่ดูแล้ว การซ่อมดาวแห่งการแปรธาตุควรจะเป็นความรับผิดชอบของนายมากกว่านะ",
  ui_story_5015_50150501_242_dialog_content = "นายเป็นพ่อบ้านไม่ใช่เหรอ?",
  ui_story_5015_50150501_243_dialog_content = "<color=#e8d9bb>แอ๊บบี้... จำเป็นต้องควบคุมสภาพแวดล้อมในเมือง</color>",
  ui_story_5015_50150501_244_dialog_content = "<color=#e8d9bb>ดังนั้น... เธอเลือกที่จะซ่อมแซมดาวแห่งการแปรธาตุเพื่อบรรลุเป้าหมายนั้น</color>",
  ui_story_5015_50150501_245_dialog_content = "บัตเลอร์ ในเมื่อตอนนี้นายได้สิทธิ์ทั้งหมดมาแล้ว ช่วยตรวจสอบสถานการณ์ปัจจุบันของดาวแห่งการแปรธาตุให้ทีได้มั้ย?",
  ui_story_5015_50150501_246_dialog_content = "โอ๊ะ จริงด้วย! ดูให้ทีสิ!",
  ui_story_5015_50150501_247_dialog_content = "<color=#e8d9bb>เริ่มการตรวจสอบดาวแห่งการแปรธาตุ</color>",
  ui_story_5015_50150501_248_dialog_content = "<color=#e8d9bb>... คลังพลังงาน... ผ่านการตรวจสอบ...</color>",
  ui_story_5015_50150501_249_dialog_content = "<color=#e8d9bb>... ความสมบูรณ์ของระบบท่อ... เสียหาย 23%...</color>",
  ui_story_5015_50150501_250_dialog_content = "<color=#e8d9bb>... การทดสอบเสถียรภาพ... ล้มเหลว...</color>",
  ui_story_5015_50150501_251_dialog_content = "<color=#e8d9bb>... กำลังเปิดใช้งานโปรแกรมซ่อมแซม...</color>",
  ui_story_5015_50150501_252_dialog_content = "<color=#e8d9bb>ผิดพลาด! ผิดพลาด! โปรแกรมซ่อมแซมขาดหายไป เปิดใช้งานไม่สำเร็จ!</color>",
  ui_story_5015_50150501_253_dialog_content = "บัตเลอร์ เกิดอะไรขึ้น?",
  ui_story_5015_50150501_254_dialog_content = "<color=#e8d9bb>ผมตรวจสอบแล้ว... พบว่ามี... โปรแกรมซ่อมแซมในข้อมูลของแอ๊บบี้</color>",
  ui_story_5015_50150501_255_dialog_content = "<color=#e8d9bb>จากข้อมูลดังกล่าว... โปรแกรมซ่อมแซมนี้เป็นวิธีซ่อมเพียงวิธีเดียวที่หลงเหลืออยู่</color>",
  ui_story_5015_50150501_256_dialog_content = "<color=#e8d9bb>แต่มันก็เสียหาย... จนถึงขั้นไม่สามารถใช้งานได้</color>",
  ui_story_5015_50150501_257_dialog_content = "<color=#e8d9bb>แม้กระนั้นแอ๊บบี้ก็ยังฝืนรัน... โปรแกรมซ่อมแซม... ทำให้ดาวแห่งการแปรธาตุเสียหายในระดับที่ไม่อาจย้อนคืน</color>",
  ui_story_5015_50150501_258_dialog_content = "ถึงว่า เวลาแอ๊บบี้พยายามซ่อมแกนพลังงานทีไรก็มีแผ่นดินไหวทุกที...",
  ui_story_5015_50150501_259_dialog_content = "นึกว่าการต่อสู้ของเราจะส่งผลกับแกนพลังงานซะอีก",
  ui_story_5015_50150501_260_dialog_content = "แล้วตอนนี้ดาวแห่งการแปรธาตุเป็นยังไงบ้าง?",
  ui_story_5015_50150501_261_dialog_content = "<color=#e8d9bb>จากการคำนวณของผม เราไม่สามารถซ่อมดาวแห่งการแปรธาตุได้อีกแล้ว... แกนพลังงานมีแต่จะสูญเสียเสถียรภาพมากขึ้นเรื่อย ๆ</color>",
  ui_story_5015_50150501_262_dialog_content = "<color=#e8d9bb>การดำเนินงานที่ต้องใช้สิทธิ์ระดับสูง... จะเพิ่มภาระให้กับดาวแห่งการแปรธาตุ</color>",
  ui_story_5015_50150501_263_dialog_content = "<color=#e8d9bb>เมื่อภาระการทำงาน... เกินขีดจำกัด ก็อาจทำให้เกิด...</color>",
  ui_story_5015_50150501_264_dialog_content = "<size=45><color=#FFB400>...การระเบิดที่รุนแรง</color></size>",
  ui_story_5015_50150601_1_dialog_content = "หา? หมายความว่าดาวแห่งการแปรธาตุมันเจ๊งจนกู่ไม่กลับแล้วใช่มั้ย?",
  ui_story_5015_50150601_2_dialog_content = "งั้นเราต้องรีบเผ่นแล้ว!",
  ui_story_5015_50150601_3_dialog_content = "แต่ว่า... บัตเลอร์ นายจะบอกทางออกกับเรารึเปล่า?",
  ui_story_5015_50150601_4_dialog_content = "นั่นสิ นายจะเปิดทางให้เราออกไปมั้ย?",
  ui_story_5015_50150601_5_dialog_content = "ยังไงนี่ก็เป็นเรื่องที่คุกคามความปลอดภัยของเมืองนะ",
